names=['export_automatic_exchange_progress.py','summarize_automatic_exchange_progress.py','automatic_exchange_progress_summary_01.json','query_critical_owner_exchange.py','critical_owner_exchange_query_01/completion.json','expand_critical_owner_scope.py','critical_owner_exchange_expansion_01/completion.json','conditional_distance_certificate.py','validate_conditional_distance_certificate.py','conditional_distance_certificate_validation_01.json','critical_owner_exchange_stage_01/binding.json','prepare_critical_owner_exchange.py','critical_owner_exchange_dev_01/registration.json','audit_native_objective_presets.py','run_registered_exchange_transactions.py','queue_critical_owner_exchange.py','paper/data/automatic_exchange_progress_v14.tex']
